{"command": "python3 << 'EOF'
import numpy as np
from PIL import Image
im = np.array(Image.open('radiograph.jpg').convert('L'), dtype=np.uint8)
H,W = im.shape
mask = im > 235
# simple BFS labeling
visited = np.zeros_like(mask, dtype=bool)
out=[]
from collections import deque
for y in range(H):
    for x in range(W):
        if mask[y,x] and not visited[y,x]:
            q=deque([(y,x)]); visited[y,x]=True; pts=[]
            while q:
                cy,cx=q.popleft(); pts.append((cy,cx))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=cy+dy,cx+dx
                    if 0<=ny<H and 0<=nx<W and mask[ny,nx] and not visited[ny,nx]:
                        visited[ny,nx]=True; q.append((ny,nx))
            if len(pts)>300:
                ys=[p[0] for p in pts]; xs=[p[1] for p in pts]
                out.append((len(pts), min(xs),max(xs),min(ys),max(ys)))
out.sort(reverse=True)
for o in out: print(f"size {o[0]}: x {o[1]}-{o[2]}, y {o[3]}-{o[4]}")
EOF", "description": "Find bright restoration clusters with BFS labeling"}
